const OnboardingFeature={id:"onboarding",name:"Onboarding",icon:"waving_hand",route:!1,data:{advisorName:"",trade:"window_coverings",advisorTitle:"independent window coverings professional",earningsMode:"manual",weeklyTarget:600,businessAddress:"",distanceUnit:"miles",measurementUnit:"mm"},init(){},render(){return`\n      <div class="fade-in minh-screen flex flex-col" >\n        <div class="flex-1 pad-scroll" >\n          <div class="fs-40 mb-sm" >👋</div>\n          <h1 class="fs-26 fw-700 mb-sm" >Welcome to Beelo</h1>\n          <p class="text-secondary mb-28 lh-150" >\n            It adapts to you — you don't adapt to it. Everything below can be changed later in Settings, so don't overthink it.\n          </p>\n\n          <div class="form-group">\n            <label>Your Full Name *</label>\n            <input type="text" class="input" id="ob-name" placeholder="e.g. Riaz Ahmed" value="${Utils.escapeHtml(this.data.advisorName)}">\n          </div>\n\n          <div class="form-group">\n            <label>Your Trade</label>\n            <select class="select" id="ob-trade" data-event="change" data-action="OnboardingFeature.changeTrade" data-args='["__value__"]'>\n              ${CONFIG.trades.map(e=>`<option value="${e.id}" ${this.data.trade===e.id?"selected":""}>${e.name}</option>`).join("")}\n            </select>\n          </div>\n\n          <div class="form-group"><label for="ob-title">How you introduce yourself</label><input type="text" class="input" id="ob-title" maxlength="160" value="${Utils.escapeHtml(this.data.advisorTitle)}"><p class="hint">Used in your message drafts. Add a company affiliation only if it is yours. Social links start blank; add your own in Settings.</p></div>\n          <details class="mb-md"><summary class="py-sm">Sales commission · set now or later</summary><label for="ob-commission-mode">How commission is estimated</label><select id="ob-commission-mode" class="select" data-event="change" data-action="OnboardingFeature.changeEarningsMode" data-args='["__value__"]'><option value="manual">Not set — no commission estimates yet</option><option value="simple">Percentage of the full sale</option><option value="two_stage">Sale reduction, then net commission</option></select>\n            <div id="ob-simple-fields" hidden><label for="ob-simple-rate">Commission (%)</label><input id="ob-simple-rate" class="input" type="number" inputmode="decimal" min="0" max="100" step="0.01"></div>\n            <div id="ob-net-fields" hidden><label for="ob-reduction">Sale reduction (%)</label><input id="ob-reduction" class="input" type="number" inputmode="decimal" min="0" max="100" step="0.01"><label for="ob-net-rate">Commission on the reduced amount (%)</label><input id="ob-net-rate" class="input" type="number" inputmode="decimal" min="0" max="100" step="0.01"></div><p class="hint">Use your actual agreement. Until configured, sales and survey commission estimates are £0. Change this later in Settings → Commission Rate. Existing pilot service-call fee rules are separate.</p>\n          </details>\n          <div class="divider-text mt-28" >Weekly Target</div>\n          <p class="text-secondary fs-13 mb-md lh-150" >\n            Compare recorded earnings with your goal before expenses and tax. Zero means no target. This is not a take-home target.\n          </p>\n          <div class="form-group">\n            <label>Weekly earnings target (£, before expenses and tax)</label>\n            <input type="number" class="input fs-24 fw-700 text-center" inputmode="decimal" id="ob-target" placeholder="600" value="${this.data.weeklyTarget}" step="10" min="0" >\n          </div>\n          <div class="flex gap-sm" >\n            ${[400,600,800,1e3].map(e=>`\n              <button type="button" class="btn btn-outline btn-sm flex-1"  data-action="OnboardingFeature.setTargetPreset" data-args='${JSON.stringify([e])}'>£${e}</button>\n            `).join("")}\n          </div>\n\n          <div class="divider-text mt-28" >Home / Business Base</div>\n          <p class="text-secondary fs-13 mb-md lh-150" >\n            Powers route distances, ETAs, mileage tax relief, and the weather glance on Home. Optional — leave blank and add it later if you'd rather.\n          </p>\n          <div class="form-group">\n            <textarea class="textarea" id="ob-address" placeholder="e.g. 12 Example Street, Manchester M14 7FZ" style="min-height:70px;">${Utils.escapeHtml(this.data.businessAddress||"")}</textarea>\n          </div>\n\n          <div class="divider-text mt-28" >Distance Unit</div>\n          <p class="text-secondary fs-13 mb-md lh-150" >\n            UK mileage tax relief is calculated in miles: 55p/mile for the first 10,000 business miles (2026/27).\n          </p>\n          <div class="segmented" id="ob-distance-segmented">\n            <button type="button" class="segment ${"miles"===this.data.distanceUnit?"active":""}" data-value="miles" data-action="OnboardingFeature.setUnit" data-args='${JSON.stringify(["distanceUnit","miles","ob-distance-segmented"])}'>Miles</button>\n            <button type="button" class="segment ${"km"===this.data.distanceUnit?"active":""}" data-value="km" data-action="OnboardingFeature.setUnit" data-args='${JSON.stringify(["distanceUnit","km","ob-distance-segmented"])}'>Kilometres</button>\n          </div>\n\n          <div class="divider-text mt-28" >Measurement Unit</div>\n          <p class="text-secondary fs-13 mb-md lh-150" >\n            Used when you measure a window for blinds/curtains on a visit.\n          </p>\n          <div class="segmented" id="ob-measurement-segmented">\n            <button type="button" class="segment ${"mm"===this.data.measurementUnit?"active":""}" data-value="mm" data-action="OnboardingFeature.setUnit" data-args='${JSON.stringify(["measurementUnit","mm","ob-measurement-segmented"])}'>mm</button>\n            <button type="button" class="segment ${"cm"===this.data.measurementUnit?"active":""}" data-value="cm" data-action="OnboardingFeature.setUnit" data-args='${JSON.stringify(["measurementUnit","cm","ob-measurement-segmented"])}'>cm</button>\n            <button type="button" class="segment ${"inches"===this.data.measurementUnit?"active":""}" data-value="inches" data-action="OnboardingFeature.setUnit" data-args='${JSON.stringify(["measurementUnit","inches","ob-measurement-segmented"])}'>in</button>\n          </div>\n\n          <section class="card mt-md" aria-labelledby="ob-storage-title"><h2 id="ob-storage-title" class="fs-18">Your records stay on this phone</h2>${"undefined"!=typeof ConsentPrompt?ConsentPrompt.explanationHtml():'<p role="alert">Storage information could not load. Reload before completing setup.</p>'}<button type="button" class="btn btn-ghost" data-action="Legal.openPage" data-args='["privacy"]'>Read privacy policy</button><label class="flex items-start gap-sm mt-sm" for="ob-storage-ack"><input type="checkbox" id="ob-storage-ack"><span>I understand where my records are stored and that I need a protected backup.</span></label></section>\n          <p id="ob-error" role="alert"></p>\n          <button class="btn btn-primary btn-block mt-xl"  data-action="OnboardingFeature.finish">\n            Start Using Beelo <span class="material-symbols-rounded">check</span>\n          </button>\n\n          <button class="btn btn-outline btn-block mt-10"  data-action="OnboardingFeature.importBackup">\n            <span class="material-symbols-rounded">restore</span>\n            Restore Backup Instead\n          </button>\n          <input type="file" id="ob-import-file" accept=".json,application/json" style="display:none;" data-action="OnboardingFeature.handleImport" data-args='["__event__"]'>\n        </div>\n      </div>\n    `},suggestedTitle:e=>"independent "+(CONFIG.trades.find(t=>t.id===e)?.name||"home-visit").toLowerCase()+" professional",changeTrade(e){const t=document.getElementById("ob-title");t&&t.value===this.suggestedTitle(this.data.trade)&&(t.value=this.suggestedTitle(e)),this.data.trade=e},changeEarningsMode(e){document.getElementById("ob-simple-fields").hidden="simple"!==e,document.getElementById("ob-net-fields").hidden="two_stage"!==e},showError(e,t){const a=document.getElementById("ob-error");a&&(a.textContent=e),Toast.show(e,"error");const n=document.getElementById(t);n?.focus(),n?.scrollIntoView?.({block:"center"})},setTargetPreset(e){this.data.weeklyTarget=e;const t=document.getElementById("ob-target");t&&(t.value=e)},setUnit(e,t,a){this.data[e]=t;const n=document.getElementById(a);n&&n.querySelectorAll(".segment").forEach(e=>{e.classList.toggle("active",e.dataset.value===t)})},importBackup(){const e=document.getElementById("ob-import-file");e&&e.click()},async handleImport(e){const t=e.target.files[0];if(t)try{await ExportService.importBackup(t),Toast.show("Backup restored","success"),App.navigate("today")}catch(e){console.error("Onboarding import failed:",e),Toast.show("Import failed: "+(e.message||"Please check the backup file"),"error")}finally{e.target.value=""}},async finish(){if(this._saving)return;const e=e=>document.getElementById(e)?.value?.trim()||"",t=e("ob-name"),a=e("ob-trade"),n=e("ob-title"),s=e("ob-target"),i=Number(s),o=e("ob-commission-mode");if(!t)return this.showError("Please enter your name","ob-name");if(!CONFIG.trades.some(e=>e.id===a))return this.showError("Choose your trade","ob-trade");if(!n||n.length>160)return this.showError("Enter how you introduce yourself (up to 160 characters)","ob-title");if(!s||!Number.isFinite(i)||i<0)return this.showError("Enter zero or a positive weekly earnings target","ob-target");if(!["manual","simple","two_stage"].includes(o))return this.showError("Choose a commission option","ob-commission-mode");const r={mode:o};for(const[t,a]of"simple"===o?[["ob-simple-rate","simpleRate"]]:"two_stage"===o?[["ob-reduction","saleReductionRate"],["ob-net-rate","netCommissionRate"]]:[]){const n=e(t),s=Number(n);if(!n||!Number.isFinite(s)||s<0||s>100)return this.showError("Enter a percentage between 0 and 100",t);r[a]=s}if(!document.getElementById("ob-storage-ack")?.checked)return this.showError("Please read and acknowledge how your records are stored","ob-storage-ack");if("undefined"==typeof ConsentPrompt||!ConsentPrompt.recordAcknowledgement())return this.showError("Could not save the storage acknowledgement. Please try again.","ob-storage-ack");const d={advisorName:t,advisorTitle:n,trade:a,weeklyTarget:i,commission:r,socialLinks:{facebook:"",instagram:""},businessAddress:e("ob-address"),distanceUnit:this.data.distanceUnit,measurementUnit:this.data.measurementUnit,advisorMode:CONFIG.advisorMode,country:CONFIG.country,currency:CONFIG.currency,taxSystem:CONFIG.taxSystem,dateFormat:CONFIG.dateFormat,onboardingComplete:!0};this._saving=!0;const l=document.querySelector('[data-action="OnboardingFeature.finish"]');l&&(l.disabled=!0);try{await DB.setSetting("config",d);try{localStorage.setItem("advisoros_config",JSON.stringify(d))}catch(e){}Object.assign(CONFIG,d),Toast.show(`Welcome, ${t}!`,"success"),App.navigate("today")}catch(e){this.showError("Could not save setup. Your entries are still here; please try again.","ob-name")}finally{this._saving=!1,l?.isConnected&&(l.disabled=!1)}}};App.registerFeature(OnboardingFeature);
